#5. Rescan Metaverse

#6. 
UPDATE CTS_DataCenter.CTSCustomerClassification AS cc
	, LATERAL (
			SELECT 	h.CustID
				,  	h.CategoryID
				, 	h.OldCategoryID AS FromCategoryID
				, 	h.DWCategoryID AS ToCategoryID
			FROM CTS_DataCenter.CTSCustomerClassification_History AS h
			WHERE h.CustID = cc.CustID
				AND h.CategoryID = 40700
				AND h.OldCategoryID IN (40400,40401,40402,40403,40404,40405,40406,40500,40501,40502,40503,40504,40505,40506,40600,40601,40602,40603,40604,40605,40606) 
			ORDER BY h.ID DESC
			LIMIT 1
		) AS h
INNER JOIN CTS_DataCenter.CustomerCategory AS cate ON cate.CategoryID = h.FromCategoryID
SET 	cc.CategoryID = h.FromCategoryID
	,	cc.ParentID = cate.ParentID
WHERE cc.CustID in (5148203,29571535,67098217,117488576,117529796,124509840,139416776,150610775,152005279,152012009,160730197,161581357,161764886,162317247,166962438,167186545,171414377,172891854,51630090,100846542,115733379,151099368,151925805,160958204,165412131);

#7. Rescan Metaverse
5148203,29571535,67098217,117488576,117529796,124509840,139416776,150610775,152005279,152012009,160730197,161581357,161764886,162317247,166962438,167186545,171414377,172891854,51630090,100846542,115733379,151099368,151925805,160958204,165412131


#8. 
UPDATE CTS_DataCenter.CTSCustomerClassification AS cc
	, LATERAL (
			SELECT 	h.CustID
				,  	h.CategoryID
				, 	h.OldCategoryID AS FromCategoryID
				, 	h.DWCategoryID AS ToCategoryID
                ,	h.LastModifiedDate 
			FROM CTS_DataCenter.CTSCustomerClassification_History AS h
			WHERE h.CustID = cc.CustID
				AND h.CategoryID = 40700
				AND h.OldCategoryID IN (40400,40401,40402,40403,40404,40405,40406,40500,40501,40502,40503,40504,40505,40506,40600,40601,40602,40603,40604,40605,40606) 
			ORDER BY h.ID DESC
			LIMIT 1
		) AS h
INNER JOIN CTS_DataCenter.CustomerCategory AS cate ON cate.CategoryID = h.FromCategoryID
SET 	cc.CategoryID = h.FromCategoryID
	,	cc.ParentID = cate.ParentID
    ,	cc.CreatedDate = h.LastModifiedDate
WHERE cc.CustID in (51630090,100846542,122089274,147931314,151099368,177081883)
	AND cc.ParentID = 40000;

